using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Windows.Forms;using System.Drawing;using NAudio.CoreAudioApi;
namespace LoopPedal {
static class SamplerChecks {
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 static float[] Tone(){var a=new float[96000];for(int i=0;i<48000;i++){a[i*2]=(float)(.2*Math.Sin(2*Math.PI*440*i/48000));a[i*2+1]=-.5f*a[i*2];}return a;}
 static double Frequency(float[] a){int from=a.Length/8,to=a.Length*3/8,c=0;for(int i=from+1;i<to;i++)if(a[(i-1)*2]<=0&&a[i*2]>0)c++;return c*48000.0/(to-from);}
 public static void Run(){var log=new List<string>();try{var source=Tone();var l=new Layer{Original=source,Audio=source,PlaybackMode=1,SnapPitch=true};SamplerPlayback.SetPitch(l,3.49);Check(l.Pitch==3,"positive semitone snap");SamplerPlayback.SetPitch(l,-3.5);Check(l.Pitch==-4,"negative half semitone");SamplerPlayback.SetStretch(l,2);Check(l.Pitch==-12&&SamplerPlayback.Time(l)==2,"linked controls");var slow=SamplerPlayback.Render(source,l.Stretch,l.Pitch,false,1,22.7,default(CancellationToken));Check(slow.Length==192000&&Math.Abs(Frequency(slow)-220)<3,"linked octave/duration");log.Add("PASS linked speed/pitch: 2x length, "+Frequency(slow)+" Hz; semitone snap");
 var cyclic=SamplerPlayback.Render(source,2,0,false,2,22.7,default(CancellationToken));Check(cyclic.Length==192000&&Math.Abs(Frequency(cyclic)-440)<25,"cyclic duration/pitch");double stereo=0;for(int i=0;i<cyclic.Length/2;i++){Check(!float.IsNaN(cyclic[i*2])&&Math.Abs(cyclic[i*2])<=.201,"cyclic finite/bounded");stereo=Math.Max(stereo,Math.Abs(cyclic[i*2+1]+.5*cyclic[i*2]));}Check(stereo<1e-6,"stereo coherence");var other=SamplerPlayback.Render(source,2,0,false,2,40,default(CancellationToken));double diff=0;for(int i=0;i<cyclic.Length;i++)diff+=Math.Abs(other[i]-cyclic[i]);Check(diff/cyclic.Length>.005,"D-time changes character");log.Add("PASS cyclic 2x duration, "+Frequency(cyclic)+" Hz; stereo coherent; D-time contrast="+diff/cyclic.Length);
 var voice=new SamplerVoice();double previous=0,step=0;for(int i=0;i<96000;i++){double left,right;voice.Read(source,i,1,12*Math.Sin(i/9000.0),1,22.7,out left,out right);if(i>100)step=Math.Max(step,Math.Abs(left-previous));previous=left;}Check(step<.04,"live linked sweep continuity "+step);log.Add("PASS linked live sweep max step="+step);
 var banks=new[]{new Engine(),new Engine()};l.PlaybackMode=2;l.CycleMs=37.5;l.Stretch=1.5;l.Pitch=3;l.Offset=0;banks[0].Layers.Add(l);var scene=PerformanceScene.Capture(banks);using(var bytes=new MemoryStream()){scene.Write(new BinaryWriter(bytes),true);bytes.Position=0;var loaded=PerformanceScene.Read(new BinaryReader(bytes));var saved=loaded.Banks[0].Layers[0];Check(saved.PlaybackMode==2&&saved.SnapPitch&&saved.CycleMs==37.5,"sampler settings roundtrip");var prepared=loaded.Prepare();Check(prepared.Banks[0].Layers[0].Stream==null&&prepared.Banks[0].Layers[0].PlaybackFrames==72000,"scene prepares cyclic mode");}log.Add("PASS sampler settings project/scene roundtrip and preparation");
 using(var form=new Pedal(true)){form.Location=new Point(-20000,-20000);form.Show();form.VerifySamplerUi();form.Close();}log.Add("PASS 2x2 Windows picker, popup bounds, clearly labelled PC loopback inputs");File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"sampler-tests.txt"),log);}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"sampler-tests.txt"),log);Environment.ExitCode=1;}}
 public static void Desktop(){try{using(var enumerate=new MMDeviceEnumerator()){var d=enumerate.GetDefaultAudioEndpoint(DataFlow.Render,Role.Multimedia);string id=d.ID,name=d.FriendlyName;int right=Math.Min(1,d.AudioClient.MixFormat.Channels-1);d.Dispose();using(var e=new Engine()){e.Open(null,null,new[]{new SourceChoice{Name="PC AUDIO · Chrome / Desktop · "+name,Endpoint=id,Left=0,Right=right,Loopback=true}},new OutputChoice{Name=name,Endpoint=id});e.Begin(false);Thread.Sleep(500);Check(e.Error==null||e.Error=="","loopback capture error "+e.Error);Check(e.Inputs[0].Take!=null&&e.Inputs[0].Take.Count>4800,"loopback records silent desktop clock");e.Finish(true);Check(e.Layers.Count==1&&e.Layers[0].Original.Length>4800,"desktop recorded layer");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"pc-loopback-tests.txt"),"PASS real WASAPI loopback start/record/finish, including silent desktop; "+name);}}}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"pc-loopback-tests.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
}
partial class Pedal {public void VerifySamplerUi(){ShowLfoPicker();Application.DoEvents();var panel=lfoPicker.Items.OfType<ToolStripControlHost>().Single().Control;var tiles=panel.Controls.OfType<LfoTile>().ToArray();if(tiles.Length!=4||tiles.Select(x=>x.Left).Distinct().Count()!=2||tiles.Select(x=>x.Top).Distinct().Count()!=2)throw new Exception("LFO 2x2 picker");using(var image=new Bitmap(lfoPicker.Width,lfoPicker.Height)){lfoPicker.DrawToBitmap(image,new Rectangle(Point.Empty,lfoPicker.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"lfo-grid-windows.png"));}lfoPicker.Close();var audio=new float[96000];var layer=new Layer{Name="Sampler UI",Original=audio,Audio=audio};loopers[0].Layers.Add(layer);RefreshTracks();ShowLayerMenu(loopers[0],layer,lfoTile);var playback=(ToolStripMenuItem)lastLayerMenu.Items.Cast<ToolStripItem>().Single(item=>item.Text=="Playback");((ToolStripMenuItem)playback.DropDownItems.Cast<ToolStripItem>().Single(item=>item.Text=="Snap pitch to semitones")).PerformClick();if(!layer.SnapPitch)throw new Exception("Semitone menu");lastLayerMenu.Close();ShowLayerMenu(loopers[0],layer,lfoTile);playback=(ToolStripMenuItem)lastLayerMenu.Items.Cast<ToolStripItem>().Single(item=>item.Text=="Playback");var algorithm=(ToolStripMenuItem)playback.DropDownItems.Cast<ToolStripItem>().Single(item=>item.Text=="Pitch / stretch");((ToolStripMenuItem)algorithm.DropDownItems.Cast<ToolStripItem>().Single(item=>item.Text.Contains("linked speed"))).PerformClick();if(layer.PlaybackMode!=1)throw new Exception("Linked menu");lastLayerMenu.Close();ShowLayerMenu(loopers[0],layer,lfoTile);playback=(ToolStripMenuItem)lastLayerMenu.Items.Cast<ToolStripItem>().Single(item=>item.Text=="Playback");algorithm=(ToolStripMenuItem)playback.DropDownItems.Cast<ToolStripItem>().Single(item=>item.Text=="Pitch / stretch");((ToolStripMenuItem)algorithm.DropDownItems.Cast<ToolStripItem>().Single(item=>item.Text=="Cyclic · S950-style")).PerformClick();if(layer.PlaybackMode!=2||layer.Stream!=null)throw new Exception("Cyclic menu");lastLayerMenu.Close();var pc=devices.Items.Cast<SourceChoice>().Where(x=>x.Loopback).ToArray();if(pc.Length==0||pc.Any(x=>!x.Name.StartsWith("PC AUDIO · Chrome / Desktop")))throw new Exception("PC audio input choices");}}
}
